toℕ-fromℕ : (n : ℕ) → toℕ (fromℕ n) ≡ n
-- Base case: when n is zero, fromℕ 0 is the element zero of Fin 1, and toℕ zero = 0, so toℕ (fromℕ 0) = 0.
toℕ-fromℕ zero = {!!}
-- Inductive case: assume toℕ (fromℕ n) = n. By the definition of fromℕ, fromℕ (suc n) is inc applied to fromℕ n. By incToℕ, toℕ (inc i) = suc (toℕ i), so toℕ (fromℕ (suc n)) = suc (toℕ (fromℕ n)). By the induction hypothesis, toℕ (fromℕ n) = n, so toℕ (fromℕ (suc n)) = suc n.
toℕ-fromℕ (suc n) = {!!}

toℕ-fromℕ : (n : ℕ) → toℕ (fromℕ n) ≡ n
-- Base case: when n is zero, fromℕ 0 is zero, and toℕ zero = 0, so toℕ (fromℕ 0) = 0.
toℕ-fromℕ ℕ.zero = {!!}
-- Inductive case: assume toℕ (fromℕ n) = n. Rewrite fromℕ (suc n) with fromℕ-suc, apply toℕ-suc, then use the induction hypothesis to get suc n.
toℕ-fromℕ (ℕ.suc n) = {!!}
